}

.layout_layout5.hook-default .mm_menus_ul .mm_menus_li:not(:nth-child(2)):after {
  display: none;
}
.container .ets_mm_megamenu .container {
  padding: 0;
}

.mm_block_type_product .thumbnail-container .product-description {
  background: none repeat scroll 0 0 rgba(0, 0, 0, 0);
  height: auto;
  position: relative;
  text-align: left;
  width: auto;
}
.layout_layout4 .mm_extra_item .cart-preview a {
  padding: 13px 0;
}
.ets-dir-rtl .mm_block_type_product .thumbnail-container .product-description,
.ets-dir-rtl .mm_block_type_product .thumbnail-container .product-title > a {
  text-align: right;
  display: block;
}

.mm_extra_item .cart-preview a {
  display: block;
  padding: 18px 0;
}
.mm_extra_item .user-info a {
  display: inline-block;
  padding: 18px 2px;
  line-height: 22px;
}
.layout_layout4 .mm_extra_item .user-info a {
    padding: 12px 2px;
}
.mm_block_type_product .thumbnail-container .thumbnail > img {
  margin-bottom: 0;
  margin-left: 0;
}
.mm_block_type_product .thumbnail-container .thumbnail {
  float: left;
  margin-right: 10px;
  width: 100px;
  margin-bottom: 10px;
}

.mm_block_type_product .thumbnail-container .thumbnail{
  border: 1px solid #D0D0D0;
  overflow: hidden;
}
.mm_block_type_product .thumbnail-container {
  box-shadow: none;
  height: auto;
  width: auto;
  margin-bottom: 10px;
  background-color: rgba(0, 0, 0, 0);
}



.mm_block_type_product .thumbnail-container:hover, .mm_block_type_product .thumbnail-container:hover .product-description {
  box-shadow: none !important;
}
.mm_block_type_product .thumbnail-container .highlighted-informations {
  box-shadow: none;
  display: none;
  position: static;
}
.mm_block_type_product .thumbnail-container .product-title > a {
  font-weight: 600;
  line-height: 18px;
  text-align: left;
}
.mm_block_type_product .thumbnail-container .product-title {
