}
.layout_layout5.skin_default:not(.scroll_heading) .mm_blocks_li {
  padding: 0 10px;
}

.hook-default .ets_mm_megamenu_content .container {
  padding: 0;
}
.hook-default.layout_layout5:not(.scroll_heading) .mm_bubble_text {
  top: -5px;
}
