    var carrier = this.getCarrier($elm.data('values'));

    if (!carrier.optionList.length) {
        $elm.remove();
        return;
    }

    var optionList = carrier.optionList.slice(0);
    optionList.reverse();
    for (var i in optionList) {
        if (i != parseInt(i)) {
            continue;
        }

        var option = optionList[i];
        this.template.prepend(
            'option',
            $elm,
            [
