  border: 1px solid rgb(1, 44, 122);
}
.btn-tel a::after,
.btn-tel a::before {
  content: "" !important;
  position: absolute;
  width: 0px;
  height: 0px;
  border-radius: 50%;
  top: 50%;
  transform: translateY(-50%);
  background: none !important;
  z-index: -1;
  transition: var(--transition);
}
.btn-tel a::after {
  right: 0;
}
.btn-tel a::before {
  left: 0;
}
.btn-tel a:hover::before,
.btn-tel a:hover::after {
  background-color: #ecf4ff !important;
  display: block !important;
}
.btn-tel a:hover::before {
  animation: left-move 0.5s linear forwards;
}
.btn-tel a:hover::after {
  animation: right-move 0.5s linear forwards;
}
@keyframes right-move {
  50% {
    right: 0;
    width: 0px;
    height: 0px;
  }
  100% {
    right: 0;
    border-radius: 0;
    width: 60%;
    height: 100%;
  }
}
@keyframes left-move {
  50% {
    left: 0;
    width: 0px;
    height: 0px;
  }
  100% {
    left: 0;
    border-radius: 0;
    width: 50%;
    height: 100%;
  }
}
