  font-size: 16px;
  position: relative;
}
#group_6 .input-radio:checked+.radio-label::before {
  box-shadow: none !important;
}
/* Conteneur principal des options d'épaisseur */
#group_6 {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 25px;
  padding: 15px 0px;
  list-style: none;
}
.radio-label:before {

  border-radius: 7px !important;

}
#group_6 .input-container {
  margin: 0;
  padding: 0;
  flex: 0 0 auto;
  position: relative;
  z-index: 1;
}
#group_6 .input-radio {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
#group_6 .radio-label {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 50px;
  height: 50px;
  border: 2px solid transparent;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  background-color: white;
  color: #495057;
  font-weight: 600;
  font-size: 15px;
  box-shadow: 0 3px 6px rgba(0,0,0,0.08);
  position: relative;
  overflow: hidden;
}

/* Effet de survol */
#group_6 .input-radio:not(:checked) + .radio-label:hover {
  transform: translateY(-5px) scale(1.05);
  box-shadow: 0 8px 15px rgba(0,0,0,0.1);
  color: #0066cc;
  border-color: rgba(0, 102, 204, 0.3);
}

/* Animation d'onde au clic */
#group_6 .radio-label::after {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle, rgba(0,102,204,0.3) 0%, rgba(255,255,255,0) 70%);
  opacity: 0;
  transform: scale(0);
  transition: all 0.5s;
  border-radius: 50%;
}

#group_6 .input-radio:not(:checked) + .radio-label:active::after {
  opacity: 1;
  transform: scale(2);
  transition: all 0.3s;
}

/* Style pour l'option sélectionnée */
#group_6 .input-radio:checked + .radio-label {
  background: linear-gradient(135deg, #0066cc, #0088ee);
  color: white;
  border-color: #0055bb;
  box-shadow: 0 6px 15px rgba(0, 102, 204, 0.4);
  transform: translateY(-7px) scale(1.08);
  font-weight: 700;
}

/* Animation pour l'option sélectionnée */
#group_6 .input-radio:checked + .radio-label::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(255,255,255,0.2) 0%, rgba(255,255,255,0) 50%);
  animation: shine 2s infinite ease-in-out;
}
#group_6 .input-radio:disabled + .radio-label {
  background-color: #f1f3f5;
  color: #adb5bd;
  cursor: not-allowed;
  border: 1px dashed #ced4da;
  box-shadow: none;
  opacity: 0.7;
  transform: none;
}
#group_6 .input-container {
  animation: fadeInUp 0.4s ease-out forwards;
}

/* Animation retardée pour chaque élément */
#group_6 .input-container:nth-child(1) { animation-delay: 0.05s; }
#group_6 .input-container:nth-child(2) { animation-delay: 0.1s; }
#group_6 .input-container:nth-child(3) { animation-delay: 0.15s; }
#group_6 .input-container:nth-child(4) { animation-delay: 0.2s; }
#group_6 .input-container:nth-child(5) { animation-delay: 0.25s; }
#group_6 .input-container:nth-child(6) { animation-delay: 0.3s; }
#group_6 .input-container:nth-child(7) { animation-delay: 0.35s; }
#group_6 .input-container:nth-child(8) { animation-delay: 0.4s; }
#group_6 .input-container:nth-child(9) { animation-delay: 0.45s; }
#group_6 .input-container:nth-child(10) { animation-delay: 0.5s; }
#group_6 .input-container:nth-child(11) { animation-delay: 0.55s; }


/* Style responsive */
@media (max-width: 576px) {
  #group_6 {
    gap: 8px;
    padding: 8px 3px;
  }

  #group_6 .radio-label {
    width: 42px;
    height: 42px;
    font-size: 14px;
    border-radius: 8px;
  }

  #group_6 .input-radio:checked + .radio-label {
    transform: translateY(-5px) scale(1.05);
  }
}

/* Animation supplémentaire pour indiquer la sélection */
#group_6 .input-radio:checked + .radio-label::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -12px;
  transform: translateX(-50%);
  width: 6px;
  height: 6px;
  background-color: #0066cc;
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(0, 102, 204, 0.5);
  animation: pulse 1.5s infinite;
}

@keyframes pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(0, 102, 204, 0.7);
  }
  70% {
    box-shadow: 0 0 0 6px rgba(0, 102, 204, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(0, 102, 204, 0);
  }
}
