function moveReviewButton() {
    const form = document.querySelector('#add-to-cart-or-refresh');
    if (!form) return;
    form.querySelectorAll('.ets-rv-product-comments-additional-info').forEach(el => el.remove());
    const review = document.querySelector('.product-additional-info .ets-rv-product-comments-additional-info');
    if (review) {
        form.insertBefore(review, form.firstChild);
        console.log('Moved review button into form.');
    }
}
function observeReviewBlock() {
    const target = document.querySelector('.product-additional-info');
    if (!target) return;

    const observer = new MutationObserver((mutations) => {
        mutations.forEach(mutation => {
            mutation.addedNodes.forEach(node => {
                if (
                    node.nodeType === 1 &&  
                    node.matches('.ets-rv-product-comments-additional-info')
                ) {
                    moveReviewButton();  
                }
            });
        });
    });
    observer.observe(target, { childList: true, subtree: true });
    if (window.prestashop && typeof window.prestashop.on === 'function') {
        window.prestashop.on('updatedProduct', moveReviewButton);
    }
}


