(function() {
    'use strict';
    function attachVoucherHandler() {
        const voucherForm = document.querySelector('.js-cart-voucher form[data-link-action="add-voucher"]');
        if (!voucherForm) return;
        const newForm = voucherForm.cloneNode(true);
        voucherForm.parentNode.replaceChild(newForm, voucherForm);
        newForm.addEventListener('submit', function(e) {
            e.preventDefault();
            const form = this;
            const formData = new FormData(form);
            const submitButton = form.querySelector('button[type="submit"]');
            const errorContainer = document.querySelector('.js-cart-voucher .js-error');
            const errorText = document.querySelector('.js-cart-voucher .js-error-text');
            if (submitButton) {
                submitButton.disabled = true;
                submitButton.innerHTML = '<span>Chargement...</span>';
            }
            if (errorContainer) {
                errorContainer.style.display = 'none';
            }
            fetch(form.action, {
                method: 'POST',
                body: formData,
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                },
                credentials: 'same-origin'
            })
            .then(response => response.json())
            .then(data => {
                if (data.hasError) {
                    if (errorContainer && errorText) {
                        errorText.textContent = data.errors[0] || 'Code invalide';
                        errorContainer.style.display = 'block';
                    }
                    if (submitButton) {
                        submitButton.disabled = false;
                        submitButton.innerHTML = '<span>Ajouter</span>';
                    }
                } else {
                    window.location.reload();
                }
            })
            .catch(error => {
                console.error('Error:', error);
                window.location.reload();
            });
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', attachVoucherHandler);
    } else {
        attachVoucherHandler();
    }
    if (window.prestashop) {
        prestashop.on('updateCart', function(event) {
            console.log('Cart updated:', event);
            setTimeout(attachVoucherHandler, 500);
        });
    }
    document.addEventListener('click', function(e) {
        const removeLink = e.target.closest('a[data-link-action="remove-voucher"], .js-remove-voucher, a[href*="deleteDiscount"]');
        if (removeLink) {
            console.log('Voucher remove clicked');
            setTimeout(function() {
                console.log('Reloading after voucher removal...');
                window.location.reload();
            }, 800);
        }
    }, true);
    const observeCart = function() {
        const cartContainer = document.querySelector('.cart-summary, .js-cart, #cart-summary-product-list');
        if (!cartContainer) return;
        const observer = new MutationObserver(function(mutations) {
            const voucherUpdated = mutations.some(function(mutation) {
                return mutation.target.closest('.js-cart-voucher') || 
                       mutation.target.classList?.contains('js-discount') ||
                       mutation.target.closest('.js-discount');
            });
            if (voucherUpdated) {
                console.log('Voucher section updated, re-attaching handler...');
                setTimeout(attachVoucherHandler, 300);
            }
        });
        observer.observe(cartContainer, {
            childList: true,
            subtree: true
        });
    };
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', observeCart);
    } else {
        observeCart();
    }

})();

