               jQuery(this).html('<div id="contactable-inner"></div><form id="contactable-contactForm" method="" action=""><div id="contactable-loading"></div><div id="contactable-callback"></div><div class="contactable-holder"><p class="contactable-header">'+options.header+'</p><p class="contactable-name">'+'<input id="contactable-name" class="contactable-contact contactable-validate" name="name" placeholder="'+options.name+'" /></p><p class="contactable-email">'+'<input id="contactable-email" class="contactable-contact contactable-validate" name="email" placeholder="'+options.email+'" value="'+options.customermail+'" /></p><p class="contactable-company">'+'<input id="contactable-company" class="contactable-contact contactable-validate" name="company" placeholder="Société" /></p><p class="contactable-phone">'+'<input id="contactable-phone" class="contactable-contact contactable-validate" name="phone" placeholder="Téléphone" /></p>'+dropdown+'<p class="contactable-text">'+'<textarea id="contactable-message" name="message" class="contactable-message contactable-validate" rows="4" cols="60" placeholder="'+options.message+'" ></textarea></p><p class="contactable-sub"><input class="contactable-submit btn btn-primary" type="submit" value="'+options.submit+'"/></p><p class="contactable-footer">'+options.footer+'</p></div></form>');

